59	/// Multiplies every clip's placement by the canvas size ratio, so a layout
60	/// built for one canvas lands in the same relative place on the next (spec
61	/// §6, `rescale_clips`).
62	///
63	/// `x` and `y` are per-axis offsets in canvas pixels, so each follows its
64	/// OWN axis ratio — that is what keeps a layer's distance from an edge
65	/// proportional when the aspect ratio changes too. `scale` is one uniform
66	/// factor and cannot follow two ratios, so it follows the SMALLER of them:
67	/// the same `min` Fit uses, which means a layer that fitted the old canvas
68	/// still fits the new one, where the larger ratio could push it off an
69	/// edge.
70	///
71	/// Action `end` patches are deliberately NOT rescaled: a patch is opaque
72	/// JSON (`actions.rs` interprets it), and the op is defined on the clip's
73	/// props. An animated move on a resized canvas therefore keeps its old
74	/// target, which is visible and fixable, unlike a patch this function
75	/// half-understood and rewrote.
76	fn rescale(project: &mut Project, old_width: u32, old_height: u32) {
77	    if old_width == 0 || old_height == 0 {
78	        return;
79	    }
80	    let width_ratio = f64::from(project.canvas.width) / f64::from(old_width);
81	    let height_ratio = f64::from(project.canvas.height) / f64::from(old_height);
82	    if !(width_ratio.is_finite() && height_ratio.is_finite()) {
83	        return;
84	    }
85	    for clip in project.clips.iter_mut() {
86	        if let Some(video) = clip.video.as_mut() {
87	            rescale_video(video, width_ratio, height_ratio);
88	        }
89	    }
90	}
