104	/// Re-snaps stored picture times to the canvas's CURRENT frame grid, after
105	/// that grid has changed.
106	///
107	/// Yesterday's grid is not today's: a 24 fps boundary is not a 30 fps
108	/// boundary, so top-level and stored-nest clips, their action and present
109	/// base motion/text times, and top-level markers move to the new grid.
110	///
111	/// Three clamps keep the result valid: a media clip's duration is held to
112	/// the source it still has, snapped DOWN to the new grid, so a coarser rate
113	/// cannot round a whole-file clip past the end of its file (spec §11); a
114	/// duration that would round to zero becomes one frame (a zero-length clip
115	/// is what `validate` rejects), which is the ONE case the source bound
116	/// cannot hold and `evaluate.rs`'s clamp covers; and an action is kept
117	/// inside its clip — but a ramped clip's speed action, which is snapped and
118	/// left running past the end, the duration held again (spec §11 SR-19 (g)).
119	fn resnap(project: &mut Project) {
120	    let fps = project.canvas.fps;
121	    // Temporarily own each list so source/media lookup can borrow the whole
122	    // project while a clip is normalized. Visit each stored nest exactly
123	    // once, including orphans and nests shown by more than one clip.
124	    let mut clips = std::mem::take(&mut project.clips);
125	    for clip in &mut clips {
126	        project.resnap_clip_times(clip);
127	    }
128	    project.clips = clips;
129	    for index in 0..project.nests.len() {
130	        let mut clips = std::mem::take(&mut project.nests[index].clips);
131	        for clip in &mut clips {
132	            project.resnap_clip_times(clip);
133	        }
134	        project.nests[index].clips = clips;
135	    }
136	    for marker in project.markers.iter_mut() {
137	        marker.time = time::snap_to_frame(marker.time, fps).max(0);
138	    }
139	    // A coarser grid can land two markers on one tick, which markers may
140	    // never share. The alternative — refusing a document-wide rate change
141	    // because two marks are 3 ms apart — is far worse than dropping the
142	    // second of them, so the first in the list keeps the tick.
143	    //
144	    // A linear scan over a `Vec` rather than a set: markers are capped at
145	    // 1024 and this runs only on a rate change.
146	    let mut taken: Vec<Ticks> = Vec::with_capacity(project.markers.len());
147	    project.markers.retain(|marker| {
148	        if taken.contains(&marker.time) {
149	            false
150	        } else {
151	            taken.push(marker.time);
152	            true
153	        }
154	    });
155	}
