@objc(ProbeDoc)
final class ProbeDoc: NSDocument {
    override class var autosavesInPlace: Bool { true }
    override func data(ofType typeName: String) throws -> Data { Data("x".utf8) }
    override func read(from data: Data, ofType typeName: String) throws {}
    override func makeWindowControllers() {
        let w = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 200, height: 100),
                         styleMask: [.titled, .closable], backing: .buffered, defer: false)
        addWindowController(NSWindowController(window: w))
    }
}

func item(_ t: String, _ s: Selector?, _ k: String = "", _ m: NSEvent.ModifierFlags = [.command]) -> NSMenuItem {
    let i = NSMenuItem(title: t, action: s, keyEquivalent: k)
    i.keyEquivalentModifierMask = m
    return i
}

func dump(_ menu: NSMenu, _ depth: Int = 0) {
    menu.update()
    for i in menu.items where !i.isSeparatorItem {
        let m = i.keyEquivalentModifierMask
        var mods = ""
        if m.contains(.control) { mods += "⌃" }
        if m.contains(.option) { mods += "⌥" }
        if m.contains(.shift) { mods += "⇧" }
        if m.contains(.command) { mods += "⌘" }
        let pad = String(repeating: "  ", count: depth)
        print("\(pad)\(i.title) | key=\(i.keyEquivalent.isEmpty ? "-" : mods + i.keyEquivalent.uppercased()) | alt=\(i.isAlternate) hidden=\(i.isHidden) enabled=\(i.isEnabled) action=\(i.action.map(NSStringFromSelector) ?? "nil")")
        if let s = i.submenu { dump(s, depth + 1) }
    }
}

final class D: NSObject, NSApplicationDelegate {
    func applicationDidFinishLaunching(_ n: Notification) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            let doc = try! NSDocumentController.shared.openUntitledDocumentAndDisplay(true)
            print("== untitled"); dump(NSApp.mainMenu!.items[1].submenu!)
            let url = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("p\(getpid()).probedoc")
            doc.save(to: url, ofType: "ProbeDocument", for: .saveAsOperation) { err in
                print("saved", err as Any)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    print("== saved"); dump(NSApp.mainMenu!.items[1].submenu!)
                    doc.updateChangeCount(.changeDone)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        print("== edited"); dump(NSApp.mainMenu!.items[1].submenu!)
                        try? FileManager.default.removeItem(at: url)
                        exit(0)
                    }
                }
            }
        }
    }
}

